// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/domain/deps.ts`. Edit the source and run `just generate`.
// The rules of `dotclaude-spec deps` and `validate`: the waves, the blocked chains, the dep cycles, and the `owns` overlaps of a change.

import { CLOSED_PACKAGE_STATES } from "./states.ts";

/** One package of the graph: its id, its wave, its deps, and its `owns`. */
export interface Node {
  readonly id: string;
  readonly wave: number;
  readonly deps: readonly string[];
  readonly owns: readonly string[];
}

/** The states that stop the packages that depend on a package. */
const STOPPING: readonly string[] = ["blocked", "canceled"];

/** The states that a package does not leave, as plain strings. */
const CLOSED: readonly string[] = CLOSED_PACKAGE_STATES;

/** The state of a package that has no event: `planned`. */
const stateOf = (
  states: Readonly<Record<string, string>>,
  id: string,
): string => states[id] ?? "planned";

/** The ids of `nodes` by wave, in the order of the waves and of `nodes`. */
export const wavesOf = (
  nodes: readonly Node[],
): { wave: number; ids: string[] }[] =>
  [...new Set(nodes.map((n) => n.wave))]
    .sort((a, b) => a - b)
    .map((wave) => ({
      wave,
      ids: nodes.filter((n) => n.wave === wave).map((n) => n.id),
    }));

/**
 * The blocked chains: for each open package that depends, at any depth, on a `blocked` or `canceled` package,
 * the path of ids from the package to the first such dep.
 */
export const blockedChains = (
  nodes: readonly Node[],
  states: Readonly<Record<string, string>>,
): string[][] => {
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const chainFrom = (id: string, seen: Set<string>): string[] | null => {
    for (const dep of byId.get(id)?.deps ?? []) {
      if (seen.has(dep)) continue;
      if (STOPPING.includes(states[dep] ?? "")) return [id, dep];
      const rest = chainFrom(dep, new Set([...seen, dep]));
      if (rest) return [id, ...rest];
    }
    return null;
  };
  const ended: readonly string[] = [...CLOSED, "blocked"];
  return nodes
    .filter((n) => !ended.includes(stateOf(states, n.id)))
    .map((n) => chainFrom(n.id, new Set([n.id])))
    .filter((chain) => chain !== null);
};

/** True when one `owns` entry of `a` is a prefix of an entry of `b`, or the other way. */
export const ownsOverlap = (
  a: readonly string[],
  b: readonly string[],
): boolean => a.some((x) => b.some((y) => x.startsWith(y) || y.startsWith(x)));

/** The pairs of open packages of one wave whose `owns` overlap, in the order of `nodes`. */
export const ownsOverlaps = (
  nodes: readonly Node[],
  states: Readonly<Record<string, string>>,
): [string, string][] => {
  const open = nodes.filter((n) => !CLOSED.includes(stateOf(states, n.id)));
  const pairs: [string, string][] = [];
  for (const [i, a] of open.entries())
    for (const b of open.slice(i + 1))
      if (a.wave === b.wave && ownsOverlap(a.owns, b.owns))
        pairs.push([a.id, b.id]);
  return pairs;
};

/** The deps that name no package of `nodes`, as `[package, dep]` pairs. */
export const missingDeps = (nodes: readonly Node[]): [string, string][] => {
  const known = new Set(nodes.map((n) => n.id));
  return nodes.flatMap((n) =>
    n.deps.filter((d) => !known.has(d)).map((d): [string, string] => [n.id, d]),
  );
};

/** The ids of the packages on a dep cycle, found by a depth-first walk of the deps. */
export const cycleMembers = (nodes: readonly Node[]): string[] => {
  const deps = new Map(nodes.map((n) => [n.id, n.deps]));
  const state = new Map<string, "visiting" | "done">();
  const stack: string[] = [];
  const members = new Set<string>();
  const visit = (id: string): void => {
    const seen = state.get(id);
    if (seen === "done") return;
    if (seen === "visiting") {
      for (const member of stack.slice(stack.indexOf(id))) members.add(member);
      return;
    }
    state.set(id, "visiting");
    stack.push(id);
    for (const dep of deps.get(id) ?? []) if (deps.has(dep)) visit(dep);
    stack.pop();
    state.set(id, "done");
  };
  for (const id of deps.keys()) visit(id);
  return [...members];
};
